const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const hash = (value) => {
  let current = 2166136261;

  for (let index = 0; index < value.length; index++) {
    current ^= value.charCodeAt(index);
    current = Math.imul(current, 16777619);
  }

  return (current >>> 0)
    .toString(16)
    .padStart(8, '0');
};

const clinic_id = Number(input.clinic_id ?? 0);
const client_id = Number(input.client_id ?? 0);
const gateway_event_type =
  text(input.gateway_event_type).toLowerCase();
const channel = text(input.channel).toLowerCase();
const external_event_id =
  text(input.external_event_id);
const external_message_id =
  text(input.external_message_id);
const source_ip = text(input.source_ip);
const request_timestamp =
  text(input.request_timestamp) ||
  new Date().toISOString();
const replay_window_seconds =
  Number(input.replay_window_seconds ?? 86400);
const confirm_check = bool(input.confirm_check);

const request_hash =
  text(input.request_hash) ||
  `req-${hash(JSON.stringify({
    clinic_id,
    client_id,
    gateway_event_type,
    channel,
    external_event_id,
    external_message_id,
    request_timestamp,
  }))}`;

const replay_key = [
  clinic_id,
  client_id,
  gateway_event_type,
  channel,
  external_event_id,
].join(':');

const errors = [];

if (
  !Number.isInteger(clinic_id) ||
  clinic_id < 1
) {
  errors.push({
    field: 'clinic_id',
    message: 'شناسه کلینیک معتبر نیست.',
  });
}

if (
  !Number.isInteger(client_id) ||
  client_id < 1
) {
  errors.push({
    field: 'client_id',
    message: 'شناسه Gateway Client معتبر نیست.',
  });
}

if (
  !['inbound_message', 'delivery_status'].includes(
    gateway_event_type
  )
) {
  errors.push({
    field: 'gateway_event_type',
    message: 'نوع رویداد Gateway معتبر نیست.',
  });
}

if (!channel) {
  errors.push({
    field: 'channel',
    message: 'کانال الزامی است.',
  });
}

if (!external_event_id) {
  errors.push({
    field: 'external_event_id',
    message: 'شناسه خارجی رویداد الزامی است.',
  });
}

if (Number.isNaN(Date.parse(request_timestamp))) {
  errors.push({
    field: 'request_timestamp',
    message: 'زمان درخواست معتبر نیست.',
  });
}

if (
  !Number.isInteger(replay_window_seconds) ||
  replay_window_seconds < 60 ||
  replay_window_seconds > 604800
) {
  errors.push({
    field: 'replay_window_seconds',
    message: 'Replay Window باید بین 60 و 604800 ثانیه باشد.',
  });
}

if (confirm_check !== true) {
  errors.push({
    field: 'confirm_check',
    message: 'بررسی Replay باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_id,
    client_id,
    gateway_event_type,
    channel,
    external_event_id,
    external_message_id,
    request_hash,
    replay_key,
    source_ip,
    request_timestamp,
    replay_window_seconds,
    confirm_check,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
